const results = [];

for (const item of $input.all()) {
  const ai = item.json.output ?? {};

  const leadScore = Number(ai.lead_score);
  const aiPriority = ai.priority;
  const qualification = ai.qualification;
  const reason = ai.reason;
  const nextAction = ai.next_action;

  const errors = [];

  // Validate lead score
  if (
    !Number.isInteger(leadScore) ||
    leadScore < 0 ||
    leadScore > 100
  ) {
    errors.push("Invalid lead_score");
  }

  // Determine priority from score
  let expectedPriority;

  if (leadScore >= 80) {
    expectedPriority = "HOT";
  } else if (leadScore >= 50) {
    expectedPriority = "WARM";
  } else {
    expectedPriority = "COLD";
  }

  // Validate AI's priority
  if (!["HOT", "WARM", "COLD"].includes(aiPriority)) {
    errors.push("Invalid priority");
  }

  // Detect disagreement between AI and business rule
  if (
    ["HOT", "WARM", "COLD"].includes(aiPriority) &&
    aiPriority !== expectedPriority
  ) {
    errors.push(
      `Priority mismatch: AI returned ${aiPriority}, but score ${leadScore} requires ${expectedPriority}`
    );
  }

  // Validate qualification
  if (
    !["QUALIFIED", "POTENTIAL", "UNQUALIFIED"].includes(qualification)
  ) {
    errors.push("Invalid qualification");
  }

  // Validate reason
  if (
    typeof reason !== "string" ||
    !reason.trim()
  ) {
    errors.push("Missing reason");
  }

  // Validate next action
  if (
    typeof nextAction !== "string" ||
    !nextAction.trim()
  ) {
    errors.push("Missing next_action");
  }

  results.push({
    json: {
      ...item.json,

      ai_result: {
        lead_score: leadScore,

        // Use deterministic business rule
        priority: expectedPriority,

        qualification,
        reason,
        next_action: nextAction
      },

      validation: {
        valid: errors.length === 0,
        errors
      }
    }
  });
}

return results;
